    int samplesPerChannel = 0;
    int totalSamples = 0;
    int bytesWritten = 0;

    for (int i = 0; i < channelCount; ++i) {
        ADPCMState state;
        state.predictor = (int16_t)((encoded[0] << 8) | encoded[1]);
        state.index = encoded[2];
        encoded += 3;

        samplesPerChannel = 0;
        int frameCount = getTrackFrameCount(); // Assume this function is defined elsewhere in the file context

        for (int j = 0; j < frameCount; ++j) {
            int16_t sample1 = decodeSample(encoded, &state);
            int16_t sample2 = decodeSample(encoded + 1, &state);
            decoded[totalSamples + samplesPerChannel] = sample1;
            decoded[totalSamples + samplesPerChannel + 1] = sample2;
            encoded += 2;
            samplesPerChannel += 2;
        }

        totalSamples += samplesPerChannel;
    }

    bytesWritten = totalSamples * sizeof(int16_t);
    return bytesWritten;
}

