    int channels = getTrackChannelCount(); // Assume this function is defined elsewhere
    int samplesDecoded = 0;
    int bytesWritten = 0;

    for (int ch = 0; ch < channels; ++ch) {
        ADPCMState state; // Assume ADPCMState is a defined structure elsewhere
        initADPCMState(&state); // Assume this function is defined elsewhere

        uint8_t* channelData = (uint8_t*)encoded + ch * (state.frameSize / channels);
        int frameCount = state.frameSize / (2 * channels); // Assuming 2 samples per frame

        for (int frame = 0; frame < frameCount; ++frame) {
            int16_t sample1 = decodeSample(channelData, &state);
            int16_t sample2 = decodeSample(channelData + 1, &state);
            decoded[samplesDecoded++] = sample1;
            decoded[samplesDecoded++] = sample2;
